def maximumSwap(digits):
    a = list(digits)
    last = [-1] * 10
    for i, d in enumerate(a):
        last[d] = i
    for i, d in enumerate(a):
        for e in range(9, d, -1):
            if last[e] > i:
                a[i], a[last[e]] = a[last[e]], a[i]
                return a
    return a
